import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { balanceDue } from './payments.js';
import { invoiceTotals } from './invoices.js';

/**
 * Generate a customer statement for invoices issued on or before a given date.
 * @param {string} customerId
 * @param {Array<{ customerId: string, number: string, issueDate: string, dueDate?: string, status: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {{ ok: true, value: { customerId: string, invoices: Array<{ number: string, issueDate: string, dueDate?: string, total: number, due: number }>, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const statementInvoices = [];
  let totalDue = 0;

  for (const invoice of invoices) {
    if (invoice.customerId !== normalizedCustomerId) continue;
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') continue;
    if (invoice.issueDate > asOf) continue;

    const totalsResult = invoiceTotals(invoice);
    if (!totalsResult.ok) continue;

    const due = balanceDue(invoice);
    const statementLine = {
      number: invoice.number,
      issueDate: invoice.issueDate,
      total: totalsResult.value.total,
      due,
    };

    if (invoice.dueDate) {
      statementLine.dueDate = invoice.dueDate;
    }

    statementInvoices.push(statementLine);
    totalDue += due;
  }

  statementInvoices.sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  return ok({
    customerId: normalizedCustomerId,
    invoices: statementInvoices,
    totalDue,
  });
}

