import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement: happy path with single issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = statement('C-001', [issuedResult.value], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2024-0001');
  assert.equal(result.value.invoices[0].issueDate, '2024-10-15');
  assert.equal(result.value.invoices[0].total, 109202);
  assert.equal(result.value.invoices[0].due, 109202);
  assert.equal(result.value.totalDue, 109202);
});

test('statement: with partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 50000, date: '2024-10-20' });
  const result = statement('C-001', [paidResult.value], '2024-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 59202); // 109202 - 50000
  assert.equal(result.value.totalDue, 59202);
});

test('statement: with fully paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 109202, date: '2024-10-20' });
  const result = statement('C-001', [paidResult.value], '2024-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement: excludes draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result = statement('C-001', [invoiceResult.value], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement: excludes invoices with issueDate after asOf', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-25',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = statement('C-001', [issuedResult.value], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement: includes invoices with issueDate exactly on asOf', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = statement('C-001', [issuedResult.value], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement: excludes other customers invoices', () => {
  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
    []
  ).value;

  const invoice2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value,
    []
  ).value;

  const result = statement('C-001', [invoice1, invoice2], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, invoice1.number);
});

test('statement: multiple invoices sorted by issueDate', () => {
  const invoice3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-25',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }).value,
    []
  ).value;

  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }).value,
    []
  ).value;

  const invoice2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-20',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }).value,
    []
  ).value;

  const result = statement('C-001', [invoice3, invoice1, invoice2], '2024-10-30');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2024-10-15');
  assert.equal(result.value.invoices[1].issueDate, '2024-10-20');
  assert.equal(result.value.invoices[2].issueDate, '2024-10-25');
});

test('statement: totalDue is sum of all dues', () => {
  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
    []
  ).value;

  const invoice2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-20',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value,
    []
  ).value;

  const paidInvoice2 = recordPayment(invoice2, { amount: 30000, date: '2024-10-22' }).value;

  const result = statement('C-001', [invoice1, paidInvoice2], '2024-10-25');

  assert.equal(result.ok, true);
  // Invoice 1: 109202 (unpaid)
  // Invoice 2: 54601 - 30000 = 24601 (partially paid)
  // Total: 109202 + 24601 = 133803
  assert.equal(result.value.totalDue, 133803);
});

test('statement: unknown customer', () => {
  const result = statement('C-999', [], '2024-10-20');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement: normalizes customerId', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
    []
  ).value;

  const result = statement(' c-001 ', [invoice], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement: includes dueDate if present', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const result = statement('C-001', [invoice], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].dueDate, '2024-10-29');
});

test('statement: omits dueDate if not present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  // Manually create an invoice without dueDate for testing
  const invoiceWithoutDueDate = {
    ...invoiceResult.value,
    status: 'issued',
    number: 'INV-2024-0001',
  };
  delete invoiceWithoutDueDate.dueDate;

  const result = statement('C-001', [invoiceWithoutDueDate], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].dueDate, undefined);
});

test('statement: with voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 10000 });
  const issuedResult = issueInvoice(withVoucher.value, []);
  const result = statement('C-001', [issuedResult.value], '2024-10-20');

  assert.equal(result.ok, true);
  // Total before voucher: 109202, after voucher: 99202
  assert.equal(result.value.invoices[0].total, 99202);
  assert.equal(result.value.invoices[0].due, 99202);
});

test('statement: empty invoice list', () => {
  const result = statement('C-001', [], '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement: invoices with different years', () => {
  const invoice2023 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-12-31',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }).value,
    []
  ).value;

  const invoice2024 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }).value,
    []
  ).value;

  const result = statement('C-001', [invoice2023, invoice2024], '2024-01-02');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2023-12-31');
  assert.equal(result.value.invoices[1].issueDate, '2024-01-01');
});

test('statement: large totalDue', () => {
  const invoices = [];
  for (let i = 0; i < 100; i++) {
    const inv = issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2024-10-15',
        lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      }).value,
      []
    ).value;
    invoices.push(inv);
  }

  const result = statement('C-001', invoices, '2024-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 100);
  assert(result.value.totalDue > 0);
});

